264	pub fn get_status(repo: &Repository) -> Result<Vec<GitFileStatus>, git2::Error> {
265	    let mut files = Vec::new();
266	    let statuses = repo.statuses(None)?;
267	
268	    for entry in statuses.iter() {
269	        if let Some(path) = entry.path() {
270	            let status = entry.status();
271	
272	            // Check if file is staged (in index)
273	            if status.is_index_new()
274	                || status.is_index_modified()
275	                || status.is_index_deleted()
276	                || status.is_index_renamed()
277	            {
278	                files.push(GitFileStatus {
279	                    path: path.to_string(),
280	                    status: format_status(status),
281	                    staged: true,
282	                });
283	            }
284	
285	            // Check if file is unstaged (in working tree)
286	            if status.is_wt_new()
287	                || status.is_wt_modified()
288	                || status.is_wt_deleted()
289	                || status.is_wt_renamed()
290	            {
291	                files.push(GitFileStatus {
292	                    path: path.to_string(),
293	                    status: format_status(status),
294	                    staged: false,
295	                });
296	            }
297	        }
298	    }
299	
300	    Ok(files)
301	}
