303	fn format_status(status: git2::Status) -> String {
304	    if status.is_index_new() || status.is_wt_new() {
305	        "added".to_string()
306	    } else if status.is_index_modified() || status.is_wt_modified() {
307	        "modified".to_string()
308	    } else if status.is_index_deleted() || status.is_wt_deleted() {
309	        "deleted".to_string()
310	    } else if status.is_index_renamed() || status.is_wt_renamed() {
311	        "renamed".to_string()
312	    } else {
313	        "unknown".to_string()
314	    }
315	}
