317	pub fn get_diff(repo: &Repository, path: &str, staged: bool) -> Result<String, git2::Error> {
318	    // Check if file is untracked
319	    let statuses = repo.statuses(None)?;
320	    let mut is_untracked = false;
321	
322	    for entry in statuses.iter() {
323	        if entry.path() == Some(path) && entry.status().is_wt_new() {
324	            is_untracked = true;
325	            break;
326	        }
327	    }
328	
329	    // For untracked files, generate diff manually
330	    if is_untracked && !staged {
331	        let workdir = repo
332	            .workdir()
333	            .ok_or_else(|| git2::Error::from_str("Repository has no working directory"))?;
334	        let file_path = workdir.join(path);
335	
336	        if let Ok(content) = std::fs::read_to_string(&file_path) {
337	            let line_count = content.lines().count();
338	            let mut diff_text = format!("@@ -0,0 +1,{} @@\n", line_count);
339	            for line in content.lines() {
340	                diff_text.push('+');
341	                diff_text.push_str(line);
342	                diff_text.push('\n');
343	            }
344	            return Ok(diff_text);
345	        }
346	    }
347	
348	    let mut diff_options = git2::DiffOptions::new();
349	    diff_options.pathspec(path);
350	
351	    let diff = if staged {
352	        let head = repo.head()?.peel_to_tree()?;
353	        repo.diff_tree_to_index(Some(&head), None, Some(&mut diff_options))?
354	    } else {
355	        repo.diff_index_to_workdir(None, Some(&mut diff_options))?
356	    };
357	
358	    let mut diff_text = String::new();
359	    diff.print(git2::DiffFormat::Patch, |_delta, _hunk, line| {
360	        let origin = line.origin();
361	        let content = std::str::from_utf8(line.content()).unwrap_or("");
362	
363	        match origin {
364	            '+' | '-' | ' ' => {
365	                diff_text.push(origin);
366	                diff_text.push_str(content);
367	            }
368	            _ => {
369	                // For other lines (headers, etc), include as-is
370	                diff_text.push_str(content);
371	            }
372	        }
373	        true
374	    })?;
375	
376	    Ok(diff_text)
377	}
