409	pub fn stage_hunk(
410	    repo: &Repository,
411	    _file_path: &str,
412	    full_diff: &str,
413	    hunk_header: &str,
414	    hunk_lines: &str,
415	) -> Result<(), git2::Error> {
416	    let workdir = repo.workdir().unwrap();
417	
418	    // Extract the first 4 lines as diff header (like GitX does)
419	    let diff_lines: Vec<&str> = full_diff.lines().collect();
420	    let diff_header = diff_lines
421	        .iter()
422	        .take(4)
423	        .cloned()
424	        .collect::<Vec<&str>>()
425	        .join("\n");
426	
427	    // Create patch: header + hunk header + hunk lines
428	    let patch = format!("{}\n{}\n{}\n", diff_header, hunk_header, hunk_lines);
429	
430	    eprintln!("=== STAGE PATCH ===");
431	    eprintln!("{}", patch);
432	    eprintln!("=== END ===");
433	
434	    // Use git apply command with --unidiff-zero and --cached
435	    let output = std::process::Command::new("git")
436	        .args(["apply", "--unidiff-zero", "--cached", "--ignore-whitespace"])
437	        .current_dir(workdir)
438	        .stdin(std::process::Stdio::piped())
439	        .stdout(std::process::Stdio::piped())
440	        .stderr(std::process::Stdio::piped())
441	        .spawn()
442	        .and_then(|mut child| {
443	            use std::io::Write;
444	            if let Some(mut stdin) = child.stdin.take() {
445	                stdin.write_all(patch.as_bytes())?;
446	            }
447	            child.wait_with_output()
448	        })
449	        .map_err(|e| git2::Error::from_str(&format!("Failed to run git apply: {}", e)))?;
450	
451	    if !output.status.success() {
452	        let stderr = String::from_utf8_lossy(&output.stderr);
453	        return Err(git2::Error::from_str(&format!(
454	            "git apply failed: {}",
455	            stderr
456	        )));
457	    }
458	
459	    Ok(())
460	}
