563	pub fn discard_hunk(
564	    repo: &Repository,
565	    _file_path: &str,
566	    full_diff: &str,
567	    hunk_header: &str,
568	    hunk_lines: &str,
569	) -> Result<(), git2::Error> {
570	    let workdir = repo.workdir().unwrap();
571	
572	    let diff_lines: Vec<&str> = full_diff.lines().collect();
573	    let diff_header = diff_lines
574	        .iter()
575	        .take(4)
576	        .cloned()
577	        .collect::<Vec<&str>>()
578	        .join("\n");
579	
580	    let patch = format!("{}\n{}\n{}\n", diff_header, hunk_header, hunk_lines);
581	
582	    // Use git apply --reverse (without --cached) to discard working tree changes
583	    let output = std::process::Command::new("git")
584	        .args([
585	            "apply",
586	            "--unidiff-zero",
587	            "--reverse",
588	            "--ignore-whitespace",
589	        ])
590	        .current_dir(workdir)
591	        .stdin(std::process::Stdio::piped())
592	        .stdout(std::process::Stdio::piped())
593	        .stderr(std::process::Stdio::piped())
594	        .spawn()
595	        .and_then(|mut child| {
596	            use std::io::Write;
597	            if let Some(mut stdin) = child.stdin.take() {
598	                stdin.write_all(patch.as_bytes())?;
599	            }
600	            child.wait_with_output()
601	        })
602	        .map_err(|e| git2::Error::from_str(&format!("Failed to run git apply: {}", e)))?;
603	
604	    if !output.status.success() {
605	        let stderr = String::from_utf8_lossy(&output.stderr);
606	        return Err(git2::Error::from_str(&format!(
607	            "git apply failed: {}",
608	            stderr
609	        )));
610	    }
611	
612	    Ok(())
613	}
