615	// Unlike the `git` CLI, libgit2's `Repository::signature()` won't fall back to
616	// an OS-derived name when `user.name` isn't set in git config. Shell out to
617	// `git var`, which is what the CLI itself uses, to match its behavior.
618	fn resolve_author_signature(repo: &Repository) -> Result<git2::Signature<'static>, git2::Error> {
619	    if let Ok(sig) = repo.signature() {
620	        return Ok(sig.to_owned());
621	    }
622	
623	    let workdir = repo
624	        .workdir()
625	        .ok_or_else(|| git2::Error::from_str("No working directory"))?;
626	
627	    let output = std::process::Command::new("git")
628	        .args(["var", "GIT_AUTHOR_IDENT"])
629	        .current_dir(workdir)
630	        .output()
631	        .map_err(|e| git2::Error::from_str(&format!("Failed to run git var: {}", e)))?;
632	
633	    if !output.status.success() {
634	        return Err(git2::Error::from_str(
635	            "Git identity not set. Run `git config --global user.name \"Your Name\"` \
636	             and `git config --global user.email \"you@example.com\"`, then try again.",
637	        ));
638	    }
639	
640	    let ident = String::from_utf8_lossy(&output.stdout);
641	    let ident = ident.trim();
642	    let (name, rest) = ident
643	        .split_once('<')
644	        .ok_or_else(|| git2::Error::from_str("Could not parse git identity"))?;
645	    let (email, _) = rest
646	        .split_once('>')
647	        .ok_or_else(|| git2::Error::from_str("Could not parse git identity"))?;
648	
649	    git2::Signature::now(name.trim(), email.trim())
650	}
