652	pub fn create_commit(repo: &Repository, message: &str, amend: bool) -> Result<String, git2::Error> {
653	    let mut index = repo.index()?;
654	    let tree_id = index.write_tree()?;
655	    let tree = repo.find_tree(tree_id)?;
656	    let signature = resolve_author_signature(repo)?;
657	
658	    if amend {
659	        let head = repo.head()?;
660	        let head_commit = head.peel_to_commit()?;
661	        let new_oid = head_commit.amend(
662	            Some("HEAD"),
663	            Some(&signature),
664	            Some(&signature),
665	            None,
666	            Some(message),
667	            Some(&tree),
668	        )?;
669	        Ok(new_oid.to_string())
670	    } else {
671	        let parent_commit = match repo.head() {
672	            Ok(head) => Some(head.peel_to_commit()?),
673	            Err(_) => None,
674	        };
675	        let parents: Vec<&git2::Commit> = parent_commit.iter().collect();
676	        let oid = repo.commit(
677	            Some("HEAD"),
678	            &signature,
679	            &signature,
680	            message,
681	            &tree,
682	            &parents,
683	        )?;
684	        Ok(oid.to_string())
685	    }
686	}
