689	pub struct BranchDeleteInfo {
690	    pub has_local: bool,
691	    pub remote_names: Vec<String>,
692	}
693	
694	pub fn get_branch_delete_info(
695	    repo: &Repository,
696	    branch_name: &str,
697	    remote_context: Option<&str>,
698	) -> Result<BranchDeleteInfo, git2::Error> {
699	    // Invoked from a specific remote's branch list: existence of that remote
700	    // ref is a given, we only need to check for a same-named local branch.
701	    if let Some(remote) = remote_context {
702	        let has_local = repo
703	            .find_branch(branch_name, git2::BranchType::Local)
704	            .is_ok();
705	        return Ok(BranchDeleteInfo {
706	            has_local,
707	            remote_names: vec![remote.to_string()],
708	        });
709	    }
710	
711	    // Invoked from the local branches list. A branch can be pushed to (and
712	    // exist on) more than one remote even though git only tracks a single
713	    // upstream, so check every configured remote rather than just upstream().
714	    repo.find_branch(branch_name, git2::BranchType::Local)?;
715	
716	    let mut remote_names = Vec::new();
717	    for remote in repo.remotes()?.iter().flatten() {
718	        let remote_branch = format!("{}/{}", remote, branch_name);
719	        if repo
720	            .find_branch(&remote_branch, git2::BranchType::Remote)
721	            .is_ok()
722	        {
723	            remote_names.push(remote.to_string());
724	        }
725	    }
726	
727	    Ok(BranchDeleteInfo {
728	        has_local: true,
729	        remote_names,
730	    })
731	}
