775	fn resolve_commit_from_ref<'repo>(
776	    repo: &'repo Repository,
777	    reference: &str,
778	) -> Result<git2::Commit<'repo>, git2::Error> {
779	    if let Ok(branch) = repo.find_branch(reference, git2::BranchType::Local) {
780	        return branch.get().peel_to_commit();
781	    }
782	    if let Ok(branch) = repo.find_branch(reference, git2::BranchType::Remote) {
783	        return branch.get().peel_to_commit();
784	    }
785	    repo.revparse_single(reference)?.peel_to_commit()
786	}
