896	pub fn get_commits(
897	    repo: &Repository,
898	    limit: usize,
899	    local_only: bool,
900	    branch_name: Option<&str>,
901	) -> Result<Vec<GitCommit>, git2::Error> {
902	    let mut revwalk = repo.revwalk()?;
903	
904	    // If specific branch requested, only walk from that branch
905	    if let Some(branch) = branch_name {
906	        // Try local branch first
907	        if let Ok(b) = repo.find_branch(branch, git2::BranchType::Local) {
908	            if let Some(target) = b.get().target() {
909	                revwalk.push(target)?;
910	            }
911	        } else if let Ok(b) = repo.find_branch(branch, git2::BranchType::Remote) {
912	            // Try remote branch
913	            if let Some(target) = b.get().target() {
914	                revwalk.push(target)?;
915	            }
916	        } else {
917	            // Try as reference
918	            let ref_name = format!("refs/remotes/{}", branch);
919	            if let Ok(reference) = repo.find_reference(&ref_name) {
920	                if let Some(target) = reference.target() {
921	                    revwalk.push(target)?;
922	                }
923	            }
924	        }
925	    } else {
926	        // Push branches based on filter
927	        let filter_branch_type = if local_only {
928	            Some(git2::BranchType::Local)
929	        } else {
930	            None // All branches
931	        };
932	
933	        for branch in repo.branches(filter_branch_type)? {
934	            let (branch, _) = branch?;
935	            if let Some(target) = branch.get().target() {
936	                revwalk.push(target)?;
937	            }
938	        }
939	    }
940	
941	    revwalk.set_sorting(git2::Sort::TIME | git2::Sort::TOPOLOGICAL)?;
942	
943	    let mut branch_map: std::collections::HashMap<git2::Oid, Vec<GitBranch>> =
944	        std::collections::HashMap::new();
945	    let is_detached = repo.head_detached().unwrap_or(false);
946	    let head_name = repo
947	        .head()
948	        .ok()
949	        .and_then(|h| h.shorthand().map(|s| s.to_string()));
950	
951	    for branch in repo.branches(None)? {
952	        let (branch, branch_type) = branch?;
953	        if let Some(name) = branch.name()? {
954	            if let Some(target) = branch.get().target() {
955	                branch_map.entry(target).or_default().push(GitBranch {
956	                    name: name.to_string(),
957	                    is_head: !is_detached && Some(name.to_string()) == head_name,
958	                    is_remote: branch_type == git2::BranchType::Remote,
959	                });
960	            }
961	        }
962	    }
963	
964	    let mut tag_map: std::collections::HashMap<git2::Oid, Vec<String>> =
965	        std::collections::HashMap::new();
966	
967	    repo.tag_foreach(|oid, name| {
968	        if let Ok(name_str) = std::str::from_utf8(name) {
969	            if let Some(tag_name) = name_str.strip_prefix("refs/tags/") {
970	                // Peel to the commit OID (handles both lightweight and annotated tags)
971	                let target_oid = repo
972	                    .find_object(oid, None)
973	                    .and_then(|obj| obj.peel(git2::ObjectType::Commit))
974	                    .map(|obj| obj.id())
975	                    .unwrap_or(oid);
976	                tag_map
977	                    .entry(target_oid)
978	                    .or_default()
979	                    .push(tag_name.to_string());
980	            }
981	        }
982	        true
983	    })?;
984	
985	    let mut commits = Vec::new();
986	    for (i, oid) in revwalk.enumerate() {
987	        if i >= limit {
988	            break;
989	        }
990	
991	        let oid = oid?;
992	        let commit = repo.find_commit(oid)?;
993	        let parents: Vec<String> = commit.parents().map(|p| p.id().to_string()).collect();
994	        let branches = branch_map.get(&oid).cloned();
995	        let tags = tag_map.get(&oid).cloned();
996	
997	        let commit_author = commit.author();
998	        let commit_committer = commit.committer();
999	
1000	        let author = GitAuthor {
1001	            name: commit_author.name().unwrap_or("").to_string(),
1002	            email: commit_author.email().unwrap_or("").to_string(),
1003	            timestamp: commit_author.when().seconds().to_string(),
1004	        };
1005	
1006	        let committer = GitAuthor {
1007	            name: commit_committer.name().unwrap_or("").to_string(),
1008	            email: commit_committer.email().unwrap_or("").to_string(),
1009	            timestamp: commit_committer.when().seconds().to_string(),
1010	        };
1011	
1012	        commits.push(GitCommit {
1013	            id: commit.id().to_string(),
1014	            message: commit.message().unwrap_or("").to_string(),
1015	            author,
1016	            committer,
1017	            parents,
1018	            branches,
1019	            tags,
1020	            lane: 0,
1021	            lines: Vec::new(),
1022	        });
1023	    }
1024	
1025	    // Calculate lanes and lines
1026	    calculate_lanes(&mut commits);
1027	
1028	    Ok(commits)
1029	}
1030	
1031	fn calculate_lanes(commits: &mut [GitCommit]) {
1032	    struct Lane {
1033	        sha: Option<String>,
1034	        color_index: usize,
1035	    }
1036	
1037	    let mut lanes: Vec<Option<Lane>> = Vec::new();
1038	    let mut color_counter = 0;
1039	
1040	    for commit in commits.iter_mut() {
1041	        let commit_id = commit.id.clone();
1042	        let mut new_lanes: Vec<Option<Lane>> = Vec::new();
1043	        let mut current_lane: Option<usize> = None;
1044	        let mut current_color = 0;
1045	        let mut found_first = false;
1046	        let mut lines: Vec<GraphLine> = Vec::new();
1047	
1048	        // First, iterate over existing lanes and pass through any that don't want this commit
1049	        for (i, lane) in lanes.iter().enumerate() {
1050	            if let Some(lane_data) = lane {
1051	                // This lane is expecting our commit
1052	                if lane_data.sha.as_ref() == Some(&commit_id) {
1053	                    if !found_first {
1054	                        found_first = true;
1055	                        current_lane = Some(new_lanes.len());
1056	                        current_color = lane_data.color_index;
1057	                        new_lanes.push(Some(Lane {
1058	                            sha: None, // Will be set to first parent
1059	                            color_index: lane_data.color_index,
1060	                        }));
1061	                        // Upper line from previous lane to current position
1062	                        lines.push(GraphLine {
1063	                            upper: true,
1064	                            from: i,
1065	                            to: new_lanes.len() - 1,
1066	                            color: lane_data.color_index,
1067	                        });
1068	                        // Lower line at current position
1069	                        if !commit.parents.is_empty() {
1070	                            lines.push(GraphLine {
1071	                                upper: false,
1072	                                from: new_lanes.len() - 1,
1073	                                to: new_lanes.len() - 1,
1074	                                color: lane_data.color_index,
1075	                            });
1076	                        }
1077	                    } else {
1078	                        // Merge - this lane converges to current_lane
1079	                        if let Some(cur_lane) = current_lane {
1080	                            lines.push(GraphLine {
1081	                                upper: true,
1082	                                from: i,
1083	                                to: cur_lane,
1084	                                color: lane_data.color_index,
1085	                            });
1086	                        }
1087	                    }
1088	                } else {
1089	                    // Not our commit, pass through
1090	                    new_lanes.push(Some(Lane {
1091	                        sha: lane_data.sha.clone(),
1092	                        color_index: lane_data.color_index,
1093	                    }));
1094	                    // Pass-through lines
1095	                    lines.push(GraphLine {
1096	                        upper: true,
1097	                        from: i,
1098	                        to: new_lanes.len() - 1,
1099	                        color: lane_data.color_index,
1100	                    });
1101	                    lines.push(GraphLine {
1102	                        upper: false,
1103	                        from: new_lanes.len() - 1,
1104	                        to: new_lanes.len() - 1,
1105	                        color: lane_data.color_index,
1106	                    });
1107	                }
1108	            } else {
1109	                // Empty lane
1110	                new_lanes.push(None);
1111	            }
1112	        }
1113	
1114	        // If we didn't find a lane expecting us, create new one
1115	        if !found_first && !commit.parents.is_empty() {
1116	            current_lane = Some(new_lanes.len());
1117	            current_color = color_counter;
1118	            new_lanes.push(Some(Lane {
1119	                sha: None,
1120	                color_index: color_counter,
1121	            }));
1122	            // Lower line for new commit
1123	            lines.push(GraphLine {
1124	                upper: false,
1125	                from: new_lanes.len() - 1,
1126	                to: new_lanes.len() - 1,
1127	                color: color_counter,
1128	            });
1129	            color_counter += 1;
1130	        }
1131	
1132	        // Set the lane for this commit
1133	        commit.lane = current_lane.unwrap_or(0);
1134	        commit.lines = lines;
1135	
1136	        // Update current lane to point to first parent
1137	        if let Some(lane_idx) = current_lane {
1138	            if let Some(first_parent) = commit.parents.first() {
1139	                if let Some(Some(lane)) = new_lanes.get_mut(lane_idx) {
1140	                    lane.sha = Some(first_parent.clone());
1141	                }
1142	            } else {
1143	                // No parents - clear the lane
1144	                new_lanes[lane_idx] = None;
1145	            }
1146	        }
1147	
1148	        // Add other parents to new lanes
1149	        for parent_id in commit.parents.iter().skip(1) {
1150	            // Check if parent already in a lane
1151	            let mut found_lane_idx = None;
1152	            for (idx, lane) in new_lanes.iter().enumerate() {
1153	                if let Some(lane_data) = lane {
1154	                    if lane_data.sha.as_ref() == Some(parent_id) {
1155	                        found_lane_idx = Some(idx);
1156	                        break;
1157	                    }
1158	                }
1159	            }
1160	
1161	            if let Some(parent_lane_idx) = found_lane_idx {
1162	                // Parent already has a lane, draw line to it
1163	                if let Some(cur_lane) = current_lane {
1164	                    // Use the parent lane's color
1165	                    let parent_color = new_lanes[parent_lane_idx]
