56	function findTreeNodeByPath(nodes: TreeNode[], path: string): TreeNode | null {
57	  for (const node of nodes) {
58	    if (node.path === path) return node;
59	    if (node.children) {
60	      const found = findTreeNodeByPath(node.children, path);
61	      if (found) return found;
62	    }
63	  }
64	  return null;
65	}
