const handleViewStashDiff = (oid: string) => {
  // The commit graph isn't mounted while in the Stage view or with no
  // branch selected, so make sure it's actually on screen first.
  setCurrentView(null);
  if (!selectedBranch) {
    const headBranch = branches.find((b) => b.is_head)?.name;
    if (headBranch) setSelectedBranch(headBranch);
  }

  // get_commits is async, so the row may not exist in the DOM yet even
  // once the graph is mounted — poll briefly instead of a single lookup.
  const tryScrollAndClick = (attemptsLeft: number) => {
    const element = document.querySelector(`[data-commit-id="${oid}"]`);
    if (element) {
      element.scrollIntoView({ behavior: "smooth", block: "center" });
      setTimeout(() => (element as HTMLElement).click(), 300);
    } else if (attemptsLeft > 0) {
      setTimeout(() => tryScrollAndClick(attemptsLeft - 1), 200);
    }
  };
  setTimeout(() => tryScrollAndClick(15), 50);
};

