4	// Matches plain `git cherry-pick <commit>`: apply the commit's changes and
5	// immediately create a new commit reusing its message and author, with the
6	// current user as committer. On conflict, don't auto-commit — that would
7	// bake in unresolved conflict markers — surface an error instead and leave
8	// the index/working tree as-is for manual resolution via the terminal.
9	pub fn cherry_pick(repo: &Repository, commit_id: &str) -> Result<String, git2::Error> {
10	    let oid = git2::Oid::from_str(commit_id)
11	        .map_err(|e| git2::Error::from_str(&format!("Invalid commit ID: {}", e)))?;
12	    let commit = repo.find_commit(oid)?;
13	
14	    repo.cherrypick(&commit, None)?;
15	
16	    let mut index = repo.index()?;
17	    if index.has_conflicts() {
18	        return Err(git2::Error::from_str(
19	            "Cherry-pick resulted in conflicts. Resolve them in a terminal, then run \
20	             `git cherry-pick --continue` (or `git cherry-pick --abort` to cancel).",
21	        ));
22	    }
23	
24	    let tree_id = index.write_tree()?;
25	    let tree = repo.find_tree(tree_id)?;
26	    let head_commit = repo.head()?.peel_to_commit()?;
27	    let committer = resolve_author_signature(repo)?;
28	
29	    let new_oid = repo.commit(
30	        Some("HEAD"),
31	        &commit.author(),
32	        &committer,
33	        commit.message().unwrap_or(""),
34	        &tree,
35	        &[&head_commit],
36	    )?;
37	
38	    repo.cleanup_state()?;
39	
40	    Ok(new_oid.to_string())
41	}
